  "summary": "The code contained a critical OS command injection vulnerability and performance issues due to blocking shell calls. I have refactored the logic to use the 'dnspython' library for safe, non-blocking lookups, improved code structure with type hints and docstrings, and introduced a configuration constant.",
  "fixed_code": "import dns.resolver\nfrom flask import Flask, jsonify, request\nimport re\n\napp = Flask(__name__)\n\nDNS_TIMEOUT = 5\n\ndef perform_dns_lookup(host: str) -> str:\n    \"\"\"Performs a DNS lookup for the provided host using dnspython.\"\"\"\n    if not re.match(r'^[a-zA-Z0-9.-]+$', host):\n        raise ValueError(\"Invalid hostname format\")\n    \n    resolver = dns.resolver.Resolver()\n    resolver.timeout = DNS_TIMEOUT\n    resolver.lifetime = DNS_TIMEOUT\n    answers = resolver.resolve(host)\n    return \", \".join([str(rdata) for rdata in answers])\n\n@app.route(\"/diagnostics/dns\")\ndef dns_lookup() -> flask.Response:\n    \"\"\"Performs a DNS lookup for the provided host.\"\"\"\n    host = request.args.get(\"host\", \"\")\n    if not host or len(host) > 253:\n        return jsonify(error=\"invalid hostname\"), 400\n    \n    try:\n        output = perform_dns_lookup(host)\n        return jsonify(output=output, returncode=0)\n    except Exception as e:\n        return jsonify(error=str(e)), 500"
